import React, { useEffect, useState } from 'react';
import { supabase } from './supabaseClient';

export type MvpTier =
  | 'bronze'
  | 'silver'
  | 'gold'
  | 'platinum'
  | 'imperial'
  | 'iron'
  | 'legendary';

// الصور السبعة مضمّنة مباشرة داخل الكود (base64) - ما تحتاج رفعها لأي مكان
// خارجي (لا GitHub ولا Supabase Storage)، تشتغل فوراً بمجرد ما تحط هذا الملف
// بمشروعك.
const TIER_IMAGE: Record<MvpTier, string> = {
  bronze: 'data:image/png;base64,',
  silver: 'data:image/png;base64,',
  gold: 'data:image/png;base64,',
  platinum: 'data:image/png;base64,',
  imperial: 'data:image/png;base64,',
  iron: 'data:image/png;base64,',
  legendary: 'data:image/png;base64,',
};

interface JixMvpBadgeProps {
  tier: MvpTier | null; // null = ما فيه صاحب MVP حالياً بهذا البث
  avatarUrl: string | null;
  fallbackLetter: string; // أول حرف من اسم صاحب المستخدم، نفس نمط باقي التطبيق
  size?: number; // القطر الكامل بالبكسل (الإطار + الصورة). افتراضي 44
  onClick?: () => void;
}

// يعرض صورة بروفايل صاحب MVP الحالي بمنتصف إطاره المزخرف حسب مستواه.
// الإطار صورة PNG شفافة من المنتصف، فنحطها فوق دائرة الأفاتار بنفس القياس بالضبط.
export const JixMvpBadge: React.FC<JixMvpBadgeProps> = ({
  tier,
  avatarUrl,
  fallbackLetter,
  size = 44,
  onClick,
}) => {
  if (!tier) return null;

  // المنطقة الشفافة بمنتصف تصاميم الإطارات الحالية تقريبًا 55% من القطر الكامل
  const avatarSize = Math.round(size * 0.55);

  return (
    <button
      onClick={onClick}
      className="relative shrink-0"
      style={{ width: size, height: size }}
    >
      {/* صورة البروفايل بالمنتصف */}
      <div
        className="absolute rounded-full overflow-hidden bg-gradient-to-br from-[#FF7A1A] to-[#8B5CF6] flex items-center justify-center font-black text-white"
        style={{
          width: avatarSize,
          height: avatarSize,
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          fontSize: avatarSize * 0.4,
        }}
      >
        {avatarUrl ? (
          <img src={avatarUrl} className="w-full h-full object-cover" />
        ) : (
          fallbackLetter
        )}
      </div>

      {/* الإطار المزخرف فوق الصورة - نفس قياس الحاوية بالضبط */}
      <img
        src={TIER_IMAGE[tier]}
        alt={tier}
        className="absolute inset-0 w-full h-full pointer-events-none select-none"
        style={{ width: size, height: size }}
      />
    </button>
  );
};

// ============================================================
// مكوّن جاهز يربط JixMvpBadge ببيانات صاحب MVP الحالي لبث معيّن
// يجيب صاحب MVP + مستواه من جدول live_streams، ويحدّث نفسه لحظياً
// كل ما تغيّر صاحب MVP (بعد أي هدية جديدة تستدعي claim_mvp)
// ============================================================

// نفس عتبات دالة get_mvp_tier بقاعدة البيانات بالضبط - لازم تبقى متطابقة
const getTierFromAmount = (amount: number): MvpTier | null => {
  if (amount >= 1000000) return 'legendary';
  if (amount >= 750000) return 'iron';
  if (amount >= 500000) return 'imperial';
  if (amount >= 100000) return 'platinum';
  if (amount >= 50000) return 'gold';
  if (amount >= 10000) return 'silver';
  if (amount >= 1000) return 'bronze';
  return null;
};

interface JixLiveMvpBadgeProps {
  liveId: string;
  size?: number;
  onOpenProfile?: (userId: string) => void;
}

export const JixLiveMvpBadge: React.FC<JixLiveMvpBadgeProps> = ({ liveId, size = 32, onOpenProfile }) => {
  const [holderId, setHolderId] = useState<string | null>(null);
  const [amount, setAmount] = useState(0);
  const [holderProfile, setHolderProfile] = useState<{
    avatar_url: string | null;
    full_name: string | null;
    handle: string | null;
  } | null>(null);

  // جلب حالة MVP الحالية + الاشتراك بالتحديثات اللحظية لنفس صف البث
  useEffect(() => {
    if (!liveId) return;

    supabase
      .from('live_streams')
      .select('mvp_holder_id, mvp_amount')
      .eq('id', liveId)
      .maybeSingle()
      .then(({ data }) => {
        setHolderId(data?.mvp_holder_id ?? null);
        setAmount(data?.mvp_amount ?? 0);
      });

    const channel = supabase
      .channel(`live_mvp_${liveId}`)
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'live_streams', filter: `id=eq.${liveId}` },
        (payload) => {
          const row = payload.new as { mvp_holder_id: string | null; mvp_amount: number };
          setHolderId(row.mvp_holder_id ?? null);
          setAmount(row.mvp_amount ?? 0);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [liveId]);

  // جلب بروفايل صاحب MVP الحالي كل ما تغيّر
  useEffect(() => {
    if (!holderId) {
      setHolderProfile(null);
      return;
    }
    supabase
      .from('profiles')
      .select('avatar_url, full_name, handle')
      .eq('id', holderId)
      .maybeSingle()
      .then(({ data }) => setHolderProfile(data ?? null));
  }, [holderId]);

  if (!holderId) return null;

  const tier = getTierFromAmount(amount);
  const name = holderProfile?.full_name || holderProfile?.handle || 'م';

  return (
    <JixMvpBadge
      tier={tier}
      avatarUrl={holderProfile?.avatar_url ?? null}
      fallbackLetter={name[0]}
      size={size}
      onClick={() => onOpenProfile?.(holderId)}
    />
  );
};
